describe('Right-Side Drawer/Slide-in Panel', () => {
  beforeEach(() => {
    cy.visit('/drawer-panel');
  });

  it('should open the drawer from the right when the trigger button is clicked', () => {
    // Verify drawer is initially closed
    cy.get('[data-testid="drawer-panel"]').should('not.exist');
    cy.get('[data-testid="drawer-trigger-button"]').should('be.visible');

    // Click the trigger button to open the drawer
    cy.get('[data-testid="drawer-trigger-button"]').click();

    // Verify drawer appears from the right
    cy.get('[data-testid="drawer-panel"]').should('be.visible');
    cy.get('[data-testid="drawer-panel"]').should('have.css', 'transform', 'translateX(0px)');
    cy.get('[data-testid="drawer-panel"]').should('have.css', 'right', '0px');

    // Verify drawer content is visible
    cy.get('[data-testid="drawer-header"]').should('contain', 'Drawer Menu');
    cy.get('[data-testid="drawer-close-button"]').should('be.visible');

    // Verify drawer overlay is visible
    cy.get('[data-testid="drawer-overlay"]').should('be.visible');
  });

  it('should close the drawer when the close button or overlay is clicked', () => {
    // Open the drawer first
    cy.get('[data-testid="drawer-trigger-button"]').click();
    cy.get('[data-testid="drawer-panel"]').should('be.visible');

    // Close the drawer using the close button
    cy.get('[data-testid="drawer-close-button"]').click();
    cy.get('[data-testid="drawer-panel"]').should('not.exist');

    // Re-open the drawer
    cy.get('[data-testid="drawer-trigger-button"]').click();
    cy.get('[data-testid="drawer-panel"]').should('be.visible');

    // Close the drawer by clicking the overlay
    cy.get('[data-testid="drawer-overlay"]').click();
    cy.get('[data-testid="drawer-panel"]').should('not.exist');

    // Verify drawer can be reopened
    cy.get('[data-testid="drawer-trigger-button"]').click();
    cy.get('[data-testid="drawer-panel"]').should('be.visible');
  });
});
